export const LERNPFAD=[{id:'schritt1',titel:'Sokrates kennenlernen',beschreibung:'Beginne mit dem Vater der westlichen Philosophie und seiner Fragetechnik.',ziel:{tab:'lexikon',philId:'sokrates'}},{id:'schritt2',titel:'Die sokratische Methode selbst üben',beschreibung:'Lerne die fünf Schritte kennen, mit denen Sokrates Scheinwissen aufdeckte.',ziel:{tab:'rhetorik'}},{id:'schritt3',titel:'Platons Höhlengleichnis verstehen',beschreibung:'Eines der berühmtesten Gedankenexperimente der Philosophiegeschichte, einfach erklärt.',ziel:{tab:'erklaerungen'}},{id:'schritt4',titel:'Aristoteles\' Goldene Mitte',beschreibung:'Wie Tugend als Mitte zwischen zwei Extremen gedacht werden kann.',ziel:{tab:'lexikon',philId:'aristoteles'}},{id:'schritt5',titel:'Stoische Gelassenheit üben',beschreibung:'Die Dichotomie der Kontrolle direkt als Übung ausprobieren.',ziel:{tab:'praxis',praxisId:'dichotomie_uebung'}},{id:'schritt6',titel:'Descartes und der radikale Zweifel',beschreibung:'„Cogito ergo sum" – wie man ein unerschütterliches Wissensfundament sucht.',ziel:{tab:'lexikon',philId:'descartes'}},{id:'schritt7',titel:'Kants Kategorischer Imperativ',beschreibung:'Das oberste Moralprinzip der Aufklärung, einfach erklärt.',ziel:{tab:'erklaerungen'}},{id:'schritt8',titel:'Sartre und die radikale Freiheit',beschreibung:'Existentialismus: Der Mensch entwirft sich selbst durch seine Entscheidungen.',ziel:{tab:'lexikon',philId:'sartre'}},{id:'schritt9',titel:'Authentizität selbst prüfen',beschreibung:'Der Sartre-inspirierte Selbstcheck: Rede ich mir Freiheit manchmal selbst aus?',ziel:{tab:'praxis',praxisId:'authentizitaet_uebung'}},{id:'schritt10',titel:'Buddhas Vier Edle Wahrheiten im Alltag',beschreibung:'Eine der einflussreichsten Lehren der Welt direkt auf dein eigenes Leben anwenden.',ziel:{tab:'praxis',praxisId:'vier_wahrheiten_uebung'}},{id:'schritt11',titel:'Erstes Quiz: Leichte Fragen zur Antike',beschreibung:'Teste, was schon hängengeblieben ist – starte mit der Schwierigkeit „leicht".',ziel:{tab:'quiz'}},{id:'schritt12',titel:'Deine erste Zitat-Sammlung anlegen',beschreibung:'Durchstöbere die Zitate nach Lebenssituation und markiere deine drei liebsten mit dem Stern.',ziel:{tab:'zitate'}}];export const UEBUNGEN_PRAXIS=[// ---- Stoizismus ----
{id:'premeditatio_uebung',titel:'Premeditatio Malorum',kategorie:'Stoizismus',bezug:['seneca','epiktet'],hintergrund:'Die Stoiker empfahlen, sich mögliche Rückschläge vorab bewusst vorzustellen – nicht um sich zu ängstigen, sondern um im Ernstfall gelassener zu reagieren und das Gute im Jetzt bewusster wahrzunehmen.',schritte:['Wähle etwas, das dir gerade wichtig ist (eine Reise, eine Beziehung, einen Job).','Stell dir für 2–3 Minuten konkret vor, wie es wäre, wenn es morgen verloren ginge.','Beobachte, welche Gefühle dabei auftauchen – Angst, Dankbarkeit, Klarheit?','Kehre bewusst in die Gegenwart zurück und benenne, was du an der jetzigen Situation schätzt.'],journalPrompt:'Was hast du bei dieser Übung über deine jetzige Situation gelernt?'},{id:'abendreflexion_uebung',titel:'Senecas Abendreflexion',kategorie:'Stoizismus',bezug:['seneca'],hintergrund:'Seneca beschrieb eine abendliche Gewohnheit, den vergangenen Tag ruhig durchzugehen – nicht um sich selbst zu verurteilen, sondern um ehrlich zu lernen.',schritte:['Geh am Abend in Gedanken den Tag noch einmal durch, vom Aufwachen bis jetzt.','Frage dich: Welchen Fehler habe ich geheilt? Welcher Schwäche bin ich begegnet? Was habe ich besser gemacht als sonst?','Bewerte nicht streng – beobachte nur, wie ein wohlwollender Beobachter.','Formuliere einen konkreten, kleinen Vorsatz für morgen.'],journalPrompt:'Was war heute dein größter Lernmoment?'},{id:'dichotomie_uebung',titel:'Dichotomie der Kontrolle',kategorie:'Stoizismus',bezug:['epiktet'],hintergrund:'Epiktets Kernprinzip: Unterscheide klar zwischen dem, was in deiner Macht steht (Urteile, Reaktionen, Anstrengung), und dem, was es nicht tut (das Verhalten anderer, äußere Ereignisse, die Vergangenheit).',schritte:['Nimm ein aktuelles Problem oder eine Sorge, die dich beschäftigt.','Zeichne zwei Spalten: „In meiner Macht" und „Nicht in meiner Macht".','Trage jeden Aspekt der Situation in die passende Spalte ein.','Konzentriere deine Energie bewusst nur auf die erste Spalte.'],journalPrompt:'Was landet bei dir überraschend oft in der Spalte „Nicht in meiner Macht"?'},{id:'blickvonoben_uebung',titel:'Der Blick von oben',kategorie:'Stoizismus',bezug:['marcaurel'],hintergrund:'Marc Aurel empfahl, sich gedanklich über die Erde zu erheben, um Alltagssorgen ihre wahre, oft kleinere Proportion zurückzugeben.',schritte:['Schließe die Augen und stell dir vor, du schwebst über deiner Stadt.','Steige gedanklich weiter auf – über das Land, den Kontinent, den Planeten.','Betrachte von dort aus dein aktuelles Problem: wie groß erscheint es jetzt?','Kehre langsam zurück und beobachte, was sich an deiner Perspektive verändert hat.'],journalPrompt:'Wie hat sich die Größe deines Problems durch den Perspektivwechsel verändert?'},// ---- Sokratische Methode ----
{id:'sokratische_selbstbefragung_uebung',titel:'Sokratische Selbstbefragung',kategorie:'Sokratische Methode',bezug:['sokrates'],hintergrund:'Sokrates deckte Scheinwissen durch beharrliches Nachfragen auf. Dieselbe Technik lässt sich auf die eigenen Überzeugungen anwenden.',schritte:['Wähle eine Überzeugung, die du für selbstverständlich hältst („Ich brauche Erfolg, um glücklich zu sein").','Frage: Was genau meine ich mit diesem Begriff? Wie würde ich ihn definieren?','Frage: Gibt es eine Situation, in der diese Überzeugung nicht zutrifft?','Frage: Woher stammt diese Überzeugung eigentlich – von mir selbst oder übernommen?','Formuliere die Überzeugung nach dieser Prüfung neu, präziser.'],journalPrompt:'Wie hat sich deine ursprüngliche Überzeugung durch das Nachfragen verändert?'},{id:'definitionsuebung',titel:'Die Definitionsübung',kategorie:'Sokratische Methode',bezug:['sokrates','platon'],hintergrund:'Viele Konflikte entstehen, weil Menschen denselben Begriff unterschiedlich verstehen. Sokrates bestand darauf, Begriffe präzise zu definieren, bevor man über sie streitet.',schritte:['Wähle einen für dich zentralen Begriff (z.B. „Erfolg", „Respekt", „Freiheit").','Schreibe eine erste, spontane Definition auf.','Suche ein Gegenbeispiel: eine Situation, die deine Definition erfüllt, aber nicht das meint, was du eigentlich sagen willst – oder umgekehrt.','Verfeinere die Definition, bis das Gegenbeispiel nicht mehr passt.'],journalPrompt:'Was hat dich an deiner ursprünglichen Definition am meisten überrascht?'},// ---- Buddhismus & Achtsamkeit ----
{id:'vier_wahrheiten_uebung',titel:'Die Vier Edlen Wahrheiten im Alltag',kategorie:'Buddhismus',bezug:['buddha'],hintergrund:'Buddhas Grundlehre lässt sich direkt auf konkretes Alltagsleiden anwenden, nicht nur abstrakt verstehen.',schritte:['Benenne ein konkretes, aktuelles Leiden oder Unbehagen (Wahrheit 1).','Frage: Woran hänge ich hier – welche Begierde oder Erwartung steckt dahinter (Wahrheit 2)?','Stell dir vor, wie es sich anfühlen würde, dieses Anhaften loszulassen (Wahrheit 3).','Überlege einen konkreten, kleinen Schritt in diese Richtung (Wahrheit 4).'],journalPrompt:'Woran, hast du gemerkt, hängst du gerade am meisten?'},{id:'anatta_uebung',titel:'Anatta-Beobachtung',kategorie:'Buddhismus',bezug:['buddha','nagarjuna'],hintergrund:'Die buddhistische Lehre vom Nicht-Selbst lässt sich durch einfache Beobachtung der eigenen Gedanken erfahrbar machen, statt nur theoretisch zu verstehen.',schritte:['Setz dich fünf Minuten ruhig hin und beobachte deine Gedanken, ohne einzugreifen.','Frage bei jedem Gedanken: Ist das „Ich", oder ist das nur ein vorbeiziehender Gedanke?','Beobachte, wie Gedanken, Gefühle und Empfindungen kommen und gehen, ohne einen festen Kern.','Notiere danach, was dir an dieser Beobachtung aufgefallen ist.'],journalPrompt:'Gab es einen Moment, in dem sich dein „Ich" weniger fest anfühlte als sonst?'},{id:'loslassen_uebung',titel:'Bewusstes Loslassen',kategorie:'Buddhismus',bezug:['buddha','laozi'],hintergrund:'Anhaftung an Ergebnisse, Meinungen anderer oder Kontrolle erzeugt laut buddhistischer und daoistischer Lehre unnötiges Leiden.',schritte:['Identifiziere etwas, an das du dich gerade besonders klammerst (ein Ergebnis, eine Erwartung, eine Kontrolle).','Frage dich: Was würde tatsächlich passieren, wenn ich das loslasse?','Formuliere einen Satz, der das Loslassen ausdrückt („Ich lasse zu, dass dieses Gespräch anders verläuft als geplant").','Wiederhole diesen Satz bewusst, wenn die Anhaftung im Alltag wieder auftaucht.'],journalPrompt:'Was genau versuchst du gerade festzuhalten – und warum fällt es so schwer?'},// ---- Existentialismus ----
{id:'authentizitaet_uebung',titel:'Der Authentizitäts-Check',kategorie:'Existentialismus',bezug:['sartre'],hintergrund:'Sartre warnte vor „schlechtem Glauben" – sich selbst vorzumachen, man hätte keine Wahl. Diese Übung deckt solche Selbsttäuschungen auf.',schritte:['Nimm eine Entscheidung oder ein Verhalten, das du mit „Ich musste das tun" oder „Ich bin halt so" rechtfertigst.','Frage ehrlich: Hätte ich wirklich anders handeln können, auch wenn es unbequem gewesen wäre?','Benenne, welche Freiheit du in dieser Situation eigentlich hattest, aber ausgeblendet hast.','Formuliere die Situation neu, als bewusste Entscheidung statt als Zwang.'],journalPrompt:'Welche Freiheit hast du dir in dieser Situation selbst nicht eingestanden?'},{id:'absurdes_uebung',titel:'Dem Absurden begegnen',kategorie:'Existentialismus',bezug:['camus'],hintergrund:'Camus schlug vor, die Kluft zwischen Sinnwunsch und einem sinnfreien Universum nicht zu verdrängen, sondern bewusst und trotzdem lebensbejahend anzunehmen.',schritte:['Benenne eine Frage, auf die du keine endgültige Antwort finden wirst („Warum bin ich hier?").','Sitz kurz mit dem Unbehagen dieser Unsicherheit, ohne es sofort wegzuerklären.','Frage dich: Was würde ich trotzdem heute tun, obwohl es keine letzte Antwort gibt?','Handle bewusst danach – als kleiner, trotziger Akt der Sinnstiftung.'],journalPrompt:'Was würdest du heute tun, wenn du die letzte Antwort auf den Sinn des Lebens endgültig aufgegeben hättest?'},// ---- Tugendethik ----
{id:'goldene_mitte_uebung',titel:'Die Goldene Mitte finden',kategorie:'Tugendethik',bezug:['aristoteles'],hintergrund:'Aristoteles verortete Tugend zwischen zwei Extremen. Diese Übung hilft, das eigene Verhalten in einem Lebensbereich neu zu kalibrieren.',schritte:['Wähle eine Eigenschaft, an der du arbeiten willst (z.B. Mut, Großzügigkeit, Ehrlichkeit).','Benenne die beiden Extreme (z.B. Feigheit und Tollkühnheit bei Mut).','Überlege: Zu welchem Extrem neigst du in letzter Zeit eher?','Formuliere eine konkrete kleine Handlung für diese Woche, die dich näher an die Mitte bringt.'],journalPrompt:'Zu welchem der beiden Extreme neigst du typischerweise – und woran erkennst du das?'},{id:'gewohnheitstracker_uebung',titel:'Der Tugend-Gewohnheitstracker',kategorie:'Tugendethik',bezug:['aristoteles'],hintergrund:'Aristoteles betonte: Tugend entsteht durch wiederholte Übung, nicht durch bloßes Wissen. Eine Woche bewusster Wiederholung verändert mehr als gute Vorsätze allein.',schritte:['Wähle eine einzige, sehr konkrete tugendhafte Handlung (z.B. „einmal am Tag ehrlich ein unangenehmes Feedback geben").','Übe sie bewusst sieben Tage in Folge, auch wenn es sich anfangs unnatürlich anfühlt.','Notiere jeden Abend kurz, wie es sich angefühlt hat.','Beobachte am Ende der Woche, ob sich die Handlung natürlicher anfühlt.'],journalPrompt:'Wie hat sich die Handlung vom ersten zum letzten Tag verändert?'},// ---- Sinnfindung ----
{id:'ikigai_uebung',titel:'Die Ikigai-Vier-Kreise-Übung',kategorie:'Sinnfindung',bezug:[],hintergrund:'Ikigai wird oft als Überschneidung vierer Fragen verstanden. Das Aufschreiben aller vier Antworten nebeneinander macht Muster sichtbar, die im Kopf allein oft verborgen bleiben.',schritte:['Schreibe auf: Was liebe ich zu tun?','Schreibe auf: Worin bin ich wirklich gut?','Schreibe auf: Was braucht die Welt (oder Menschen um mich) von mir?','Schreibe auf: Womit könnte ich meinen Lebensunterhalt bestreiten?','Suche nach Überschneidungen zwischen den vier Listen.'],journalPrompt:'Welche Überschneidung zwischen deinen vier Listen hat dich am meisten überrascht?'},// ---- Ästhetik ----
{id:'wabisabi_uebung',titel:'Wabi-Sabi-Wahrnehmungsübung',kategorie:'Ästhetik',bezug:['rikyu'],hintergrund:'Wabi-Sabi lädt dazu ein, Schönheit gerade in Unvollkommenheit und Gebrauchsspuren zu entdecken, statt nur makellose Perfektion zu schätzen.',schritte:['Suche einen alten, abgenutzten oder unperfekten Gegenstand in deiner Umgebung.','Betrachte ihn zwei Minuten lang bewusst, ohne ihn zu bewerten.','Frage dich: Welche Geschichte erzählen seine Gebrauchsspuren?','Notiere, was an seiner Unvollkommenheit tatsächlich Schönheit besitzt.'],journalPrompt:'Was hat die Unvollkommenheit dieses Gegenstands dir erzählt?'},{id:'mononoaware_uebung',titel:'Mono no Aware Tagebuch',kategorie:'Ästhetik',bezug:['motoori'],hintergrund:'Mono no Aware beschreibt die wehmütige Schönheit, die in der Vergänglichkeit der Dinge liegt – bewusst wahrgenommen wird sie zu einer eigenen Form der Wertschätzung.',schritte:['Beobachte heute bewusst einen vergänglichen Moment (ein Sonnenuntergang, ein Gespräch, eine Jahreszeit).','Erlaube dir, die leise Wehmut zu spüren, dass dieser Moment nicht bleibt.','Frage dich: Was macht diesen Moment gerade wegen seiner Vergänglichkeit besonders?','Schreibe einen kurzen Satz, der diesen Moment festhält.'],journalPrompt:'Welchen vergänglichen Moment hast du heute bewusst wahrgenommen?'},{id:'montaigne_essay_uebung',titel:'Der Montaigne-Selbstversuch',kategorie:'Sokratische Methode',bezug:['montaigne'],hintergrund:'Montaigne machte das ehrliche, offene Nachdenken über das eigene Leben selbst zur philosophischen Methode – ohne vorschnelle Antworten oder moralische Selbstverurteilung.',schritte:['Wähle eine eigene Überzeugung oder Gewohnheit, über die du selten nachdenkst.','Schreibe fünf Minuten frei darüber, ohne dich zu zensieren: Woher kommt sie? Wann hat sie dir genützt, wann geschadet?','Frage dich am Ende: Was habe ich über mich selbst erfahren, das ich vorher nicht wusste?','Lies dir das Geschriebene laut vor, wie ein Außenstehender.'],journalPrompt:'Was hat dich beim Schreiben über dich selbst am meisten überrascht?'},{id:'willezumglauben_uebung',titel:'Das Willens-zum-Glauben-Experiment',kategorie:'Existentialismus',bezug:['james'],hintergrund:'William James vertrat, dass es bei existenziellen Fragen ohne zwingende Beweise legitim sein kann, sich bewusst für eine hilfreiche Überzeugung zu entscheiden.',schritte:['Wähle eine Überzeugung, die dir nicht zwingend bewiesen, aber für dein Leben hilfreich erscheint (z.B. „Ich kann diese Fähigkeit noch lernen").','Handle für einen Tag bewusst so, als wäre diese Überzeugung wahr.','Beobachte am Abend: Was hat sich in deinem Verhalten oder Gefühl dadurch verändert?','Entscheide, ob du diese Überzeugung testweise beibehältst.'],journalPrompt:'Was hat sich verändert, als du so gehandelt hast, als wäre die Überzeugung wahr?'},{id:'grenzsituation_uebung',titel:'Grenzsituation-Reflexion',kategorie:'Existentialismus',bezug:['jaspers'],hintergrund:'Jaspers zufolge zwingen uns Extremsituationen wie Tod, Leid oder Schuld zu echter Selbsterkenntnis, die im Alltag verborgen bleibt.',schritte:['Erinnere dich an eine vergangene Grenzsituation deines Lebens (schwere Krankheit, Verlust, große Schuld, Krise).','Frage dich: Was habe ich in diesem Moment über mich selbst erfahren, das ich sonst nicht gewusst hätte?','Frage dich: Wie hat sich mein Blick auf das Leben danach verändert?','Überlege, ob diese Erkenntnis heute noch in deinem Alltag lebendig ist.'],journalPrompt:'Welche Erkenntnis aus dieser Grenzsituation trägst du bis heute in dir?'},{id:'antlitz_uebung',titel:'Die Begegnung mit dem Antlitz',kategorie:'Ethik',bezug:['levinas'],hintergrund:'Levinas zufolge entsteht ethische Verpflichtung unmittelbar in der Begegnung mit dem Gesicht eines anderen Menschen – noch bevor wir bewusst darüber nachdenken.',schritte:['Suche heute bewusst ein echtes Gespräch mit direktem Blickkontakt.','Achte während des Gesprächs bewusst auf das Gesicht deines Gegenübers, statt nur zuzuhören oder zu antworten.','Beobachte, welche unmittelbaren Impulse (Fürsorge, Verantwortung) dabei entstehen, ganz ohne Nachdenken.','Notiere danach, was dir an diesem bewussten Hinsehen aufgefallen ist.'],journalPrompt:'Was hast du gespürt, als du dem Gesicht deines Gegenübers bewusst Aufmerksamkeit geschenkt hast?'},{id:'weil_aufmerksamkeit_uebung',titel:'Die Aufmerksamkeits-Übung',kategorie:'Ethik',bezug:['weil'],hintergrund:'Simone Weil hielt reine, uneigennützige Aufmerksamkeit für die höchste Form von Liebe und Gebet – schwerer zu üben, als es klingt.',schritte:['Wähle eine Person oder einen Gegenstand für diese Übung.','Richte fünf Minuten lang deine volle Aufmerksamkeit darauf, ohne zu urteilen, zu vergleichen oder eigene Gedanken einzumischen.','Bemerke, wie oft dein Geist abschweift, und kehre jedes Mal sanft zurück.','Reflektiere danach: Wie fühlt sich diese Form von Aufmerksamkeit im Vergleich zu deinem gewöhnlichen Zuhören an?'],journalPrompt:'Wie oft ist dein Geist abgeschweift, und wie hat sich reine Aufmerksamkeit angefühlt?'},// ---- Angewandte Ethik: Dilemmata ----
{id:'trolley_klassisch_uebung',titel:'Das klassische Trolley-Problem',kategorie:'Angewandte Ethik',bezug:['foot'],hintergrund:'Eine außer Kontrolle geratene Bahn rast auf fünf Menschen zu, die auf dem Gleis festgebunden sind. Du stehst an einer Weiche. Legst du sie um, fährt die Bahn auf ein Nebengleis, wo nur eine Person stirbt.',schritte:['Lies das Dilemma noch einmal langsam durch und stell es dir konkret vor.','Entscheide zuerst aus dem Bauch heraus: Würdest du die Weiche umlegen?','Prüfe deine Entscheidung aus utilitaristischer Sicht (Was rettet die meisten Leben?) und aus pflichtethischer Sicht (Darf ich aktiv jemanden zum Mittel machen?).','Halte fest, welches Argument für dich letztlich den Ausschlag gibt – und welches nicht.'],journalPrompt:'Wie hast du dich entschieden, und welches Argument hat dich am meisten überzeugt?'},{id:'fatman_uebung',titel:'Die Fat-Man-Variante',kategorie:'Angewandte Ethik',bezug:['thomson'],hintergrund:'Gleiche Ausgangslage: Fünf Menschen sind in Gefahr. Diesmal stehst du auf einer Brücke neben einer sehr schweren Person. Nur wenn du sie hinunterstößt, stoppt ihr Körper die Bahn und rettet die fünf – eine Weiche gibt es nicht.',schritte:['Vergleiche dieses Dilemma bewusst mit dem klassischen Trolley-Problem: Die Opferzahl ist identisch (eine statt fünf).','Frage dich ehrlich: Fühlt sich diese Entscheidung anders an als das Umlegen der Weiche? Warum?','Prüfe, ob der Unterschied zwischen „jemanden als Werkzeug benutzen" und „eine Nebenfolge in Kauf nehmen" für dich moralisch relevant ist.','Formuliere in einem Satz, was für dich den entscheidenden Unterschied zwischen beiden Fällen ausmacht – falls es einen gibt.'],journalPrompt:'Was macht für dich den Unterschied zwischen der Weichen-Variante und der Brücken-Variante aus – oder gibt es keinen?'},{id:'rettungsboot_uebung',titel:'Das Rettungsboot-Dilemma',kategorie:'Angewandte Ethik',bezug:['foot','thomson'],hintergrund:'Ein überfülltes Rettungsboot nach einem Schiffsunglück wird bei zu viel Gewicht sinken und alle Insassen mit sich reißen. Nur wenn eine Person das Boot verlässt, überleben die übrigen.',schritte:['Überlege: Darf jemand gezwungen werden, das Boot zu verlassen, oder darf das nur freiwillig geschehen?','Prüfe, ob es einen moralischen Unterschied macht, nach welchem Kriterium ausgewählt wird (Los, Alter, körperliche Schwäche, Freiwilligkeit).','Frage dich, ob deine eigene Antwort sich ändert, wenn du dir vorstellst, selbst im Boot zu sitzen, ohne zu wissen, welche Rolle du einnimmst.','Vergleiche dein Ergebnis mit deiner Position beim Trolley-Problem.'],journalPrompt:'Welches Auswahlkriterium erschien dir am ehesten gerechtfertigt, und warum?'},{id:'transplantation_uebung',titel:'Der Transplantations-Fall',kategorie:'Angewandte Ethik',bezug:['foot'],hintergrund:'Ein Chirurg hat fünf Patienten, die je ein anderes Organ benötigen, um zu überleben. Ein gesunder Patient kommt zur Routineuntersuchung. Würde der Chirurg ihn töten und seine Organe verteilen, könnten fünf Menschenleben gerettet werden.',schritte:['Vergleiche diesen Fall mit dem klassischen Trolley-Problem: Auch hier stirbt eine Person, um fünf zu retten.','Frage dich, warum die meisten Menschen diesen Fall viel entschiedener ablehnen als das Umlegen der Weiche.','Prüfe, ob der Unterschied darin liegt, dass hier ein unbeteiligter Mensch aktiv zum Mittel für die Rettung anderer gemacht wird.','Formuliere, welche Rolle Vertrauen (in Ärzte, in Institutionen) für deine moralische Bewertung dieses Falls spielt.'],journalPrompt:'Warum, glaubst du, fühlt sich dieser Fall anders an als das klassische Trolley-Problem, obwohl die Opferzahl gleich ist?'},{id:'steelman_uebung',titel:'Die Steelman-Übung',kategorie:'Sokratische Methode',bezug:['foot'],hintergrund:'Statt die schwächste Version einer gegnerischen Position anzugreifen (Strohmann), formuliert man bewusst ihre stärkste, überzeugendste Fassung — das schärft das eigene Denken erheblich.',schritte:['Wähle eine Position, der du entschieden widersprichst.','Schreib die drei besten, ernsthaftesten Argumente auf, die ein kluger Vertreter dieser Position bringen würde — ganz ohne sie zu entkräften.','Lies dir die Argumente laut vor, als würdest du sie selbst vertreten.','Frage dich erst danach: Was genau überzeugt mich trotzdem nicht?'],journalPrompt:'Welches der drei Argumente war am schwersten zu widerlegen?'},{id:'praemeditatio_gespraech_uebung',titel:'Das schwierige Gespräch vorwegdenken',kategorie:'Stoizismus',bezug:['epiktet','seneca'],hintergrund:'Vor einem unangenehmen Gespräch (Kündigung, Kritik, Konflikt) hilft es, sich stoisch die möglichen Reaktionen des Gegenübers vorwegzunehmen — nicht um zu befürchten, sondern um innerlich vorbereitet zu sein.',schritte:['Stell dir das bevorstehende schwierige Gespräch konkret vor.','Denke die unangenehmste mögliche Reaktion des anderen durch, ohne sie zu verdrängen.','Frage dich: Was steht davon wirklich in meiner Macht, was nicht?','Formuliere einen Satz, mit dem du innerlich ruhig in das Gespräch gehen kannst, unabhängig vom Ausgang.'],journalPrompt:'Was genau lag an deiner Sorge außerhalb deiner Kontrolle, und was lag wirklich in deiner Hand?'},{id:'werte_klarheit_uebung',titel:'Werte-Klarheits-Übung',kategorie:'Existentialismus',bezug:['sartre'],hintergrund:'Sartre zufolge entwerfen wir uns durch unsere Entscheidungen selbst. Diese Übung macht sichtbar, ob dein Alltag tatsächlich mit deinen erklärten Werten übereinstimmt.',schritte:['Schreibe deine drei wichtigsten Lebenswerte auf (z.B. Familie, Kreativität, Sicherheit).','Schau dir ehrlich deinen letzten typischen Wochenkalender an.','Frage dich: Wie viel Zeit und Energie ist tatsächlich in diese drei Werte geflossen?','Wähle eine kleine, konkrete Anpassung für die kommende Woche.'],journalPrompt:'Wo klaffen dein erklärter Wert und dein tatsächliches Zeitbudget am weitesten auseinander?'},{id:'sokratischer_dialog_selbst_uebung',titel:'Der innere sokratische Dialog',kategorie:'Sokratische Methode',bezug:['sokrates'],hintergrund:'Man kann die sokratische Methode auch auf sich selbst anwenden, statt nur im Gespräch mit anderen — als eine Art strukturierte Selbstbefragung bei wichtigen Entscheidungen.',schritte:['Formuliere eine Entscheidung, vor der du gerade stehst, als klare Aussage.','Frage dich fünfmal hintereinander „Warum?" zu deiner eigenen Begründung, wie ein Kind es tun würde.','Beobachte, an welcher Stelle deine Begründungen dünner werden.','Prüfe, ob die ursprüngliche Entscheidung diesem Test standhält.'],journalPrompt:'Bei welchem „Warum?" wurde deine Begründung am unsichersten?'},{id:'ubuntu_gemeinschaft_uebung',titel:'Ubuntu-Reflexion',kategorie:'Ethik',bezug:['mbiti'],hintergrund:'Der Ubuntu-Gedanke „Ich bin, weil wir sind" lädt dazu ein, das eigene Selbstverständnis bewusst über die eigenen Beziehungen zu definieren, statt rein individualistisch.',schritte:['Liste fünf Menschen auf, die dich zu dem gemacht haben, wer du heute bist.','Schreibe zu jedem eine konkrete Sache, die du von ihnen übernommen hast.','Frage dich: Wie viel von „meiner" Identität ist tatsächlich eigenständig entstanden, wie viel durch Beziehungen?','Überlege, wem du selbst gerade in ähnlicher Weise etwas mitgibst.'],journalPrompt:'Welche Eigenschaft an dir hättest du ohne eine bestimmte Beziehung nicht entwickelt?'},{id:'ataraxia_uebung',titel:'Epikureische Bedürfnis-Sortierung',kategorie:'Ethik',bezug:['epikur'],hintergrund:'Epikur unterschied natürliche und notwendige Bedürfnisse von bloß eingebildeten. Diese Übung macht sichtbar, wie viel Energie in eigentlich unnötige Wünsche fließt.',schritte:['Liste zehn Dinge auf, die du dir gerade wünschst oder um die du dich sorgst.','Sortiere jedes in: natürlich & notwendig / natürlich, aber nicht notwendig / weder natürlich noch notwendig.','Betrachte die dritte Kategorie besonders kritisch: Woher kommt dieser Wunsch wirklich?','Wähle einen Punkt aus der dritten Kategorie, den du bewusst eine Woche lang loslässt.'],journalPrompt:'Welcher Wunsch aus der dritten Kategorie hat dich am meisten überrascht?'},{id:'sunzi_selbsterkenntnis_uebung',titel:'Sunzis Selbst- und Lageerkenntnis',kategorie:'Angewandte Ethik',bezug:['sunzi'],hintergrund:'Sunzis Grundsatz „Kenne dich selbst und kenne deinen Gegner" lässt sich auf jede Art von Konflikt oder Verhandlung übertragen, nicht nur auf Kriegsführung.',schritte:['Wähle eine anstehende Verhandlung oder einen Konflikt.','Schreibe drei eigene Stärken und drei eigene Schwachpunkte in dieser Situation auf.','Schreibe dieselben drei Kategorien aus Sicht der anderen Seite.','Überlege: Welche Vorbereitung würde dir den größten Vorteil verschaffen, bevor das eigentliche Gespräch beginnt?'],journalPrompt:'Welche eigene Schwäche hast du bisher am meisten unterschätzt?'}];export const STECKBRIEFE=[{id:'sokrates',biografie:'Sohn eines Steinmetzen in Athen, kämpfte als Hoplit im Peloponnesischen Krieg und ging Zeit seines Lebens meist barfuß, unabhängig vom Wetter. Verfasste selbst nie eine Zeile – alles, was wir über ihn wissen, stammt aus den Schriften seiner Schüler, vor allem Platons. 399 v. Chr. wegen „Verderbens der Jugend" und „Gottlosigkeit" zum Tode durch den Schierlingsbecher verurteilt.',theorie:'Entwickelte die Mäeutik, eine Fragetechnik, die Scheinwissen durch gezielte Nachfragen entlarvt. Vertrat, dass niemand freiwillig Böses tue – Fehlverhalten entstehe aus Unwissenheit, echtes Wissen führe automatisch zu gutem Handeln.',funfact:'Laut Platons „Symposion" konnte Sokrates stundenlang bewegungslos an einem Fleck stehen, tief in Gedanken versunken – einmal angeblich eine ganze Nacht lang, bis zum Sonnenaufgang.',kritik:'Da Sokrates selbst nichts schrieb, lässt sich kaum trennen, was „echter" Sokrates und was literarische Erfindung Platons ist – manche Forscher zweifeln, ob der „historische Sokrates" überhaupt rekonstruierbar ist.'},{id:'platon',biografie:'Eigentlich Aristokles genannt – „Platon" (der „Breite") war wohl ein Spitzname wegen seines kräftigen Baus als Ringer. Stammte aus einer aristokratischen Athener Familie, gründete um 387 v. Chr. die Akademie, die erste dauerhafte philosophische Lehreinrichtung Europas.',theorie:'Entwickelte die Ideenlehre: Hinter der veränderlichen Sinnenwelt liege eine Welt ewiger, unveränderlicher Ideen als wahre Wirklichkeit. Entwarf im „Staat" ein Modell idealer Herrschaft durch philosophisch gebildete „Philosophenkönige".',funfact:'Reiste nach Sokrates\' Tod dreimal nach Syrakus, um den dortigen Tyrannen zu einem „Philosophenkönig" zu erziehen – scheiterte jedes Mal, wurde einmal sogar fast als Sklave verkauft.',kritik:'Karl Popper kritisierte Platons Idealstaat in „Die offene Gesellschaft und ihre Feinde" scharf als proto-totalitär: strenge Zensur von Kunst, starre Klassenordnung und die Unterdrückung individueller Freiheit zugunsten eines vermeintlichen Kollektivwohls.'},{id:'aristoteles',biografie:'Sohn eines Leibarztes am makedonischen Königshof, studierte 20 Jahre an Platons Akademie, wurde später Lehrer Alexanders des Großen. Gründete in Athen seine eigene Schule, das Lykeion, und verfasste Schriften zu praktisch jedem damals bekannten Wissensgebiet – von Logik über Biologie bis Poetik.',theorie:'Begründete die formale Logik und empirische Methode. Sah Eudaimonia (Glückseligkeit) als höchstes menschliches Ziel, erreichbar durch tugendhaftes Handeln in der „goldenen Mitte" zwischen zwei Extremen.',funfact:'Sezierte eigenhändig zahlreiche Tierarten für seine biologischen Schriften und gilt manchen Wissenschaftshistorikern als erster echter empirischer Biologe der Geschichte.',kritik:'Verteidigte Sklaverei und die vermeintlich „natürliche" Unterlegenheit von Frauen als Teil seiner Naturphilosophie – Positionen, die aus heutiger Sicht klar als Rechtfertigung bestehender gesellschaftlicher Machtverhältnisse seiner Zeit gelten.'},{id:'diogenes',biografie:'Wurde aus seiner Heimatstadt Sinope verbannt, angeblich wegen „Falschmünzerei" – möglicherweise wörtlich wie auch symbolisch gemeint („bestehende Werte umprägen"). Lebte danach in Athen demonstrativ besitzlos, Berichten zufolge in einem großen Tongefäß.',theorie:'Begründete zusammen mit seinem Lehrer Antisthenes den Kynismus: radikale Bedürfnislosigkeit als Weg zu wahrer Freiheit, verbunden mit provokanter Missachtung gesellschaftlicher Konventionen.',funfact:'Der Überlieferung nach durchsuchte er tagsüber mit einer brennenden Laterne die Straßen Athens „auf der Suche nach einem ehrlichen Menschen" – und fand angeblich keinen.',kritik:'Sein radikaler Provokationsstil bot kaum ein konstruktives positives Programm jenseits der reinen Ablehnung gesellschaftlicher Normen – Kritiker sehen darin mehr Show als systematische Philosophie.'},{id:'epikur',biografie:'Gründete in Athen „Den Garten", eine philosophische Gemeinschaft, die ungewöhnlich für die Zeit auch Frauen und Sklaven als vollwertige Mitglieder aufnahm. Lebte selbst zurückgezogen und bescheiden, trotz seines Rufs als „Lustphilosoph".',theorie:'Lust, verstanden als Schmerz- und Angstfreiheit (Ataraxia), sei das höchste Gut – erreichbar durch einfache Bedürfnisse, Freundschaft und die philosophische Überwindung der Todesfurcht.',funfact:'Entgegen seinem späteren Ruf als Genussphilosoph lebte Epikur selbst äußerst genügsam von Brot und Wasser und bezeichnete Käse als besonderen Luxus.',kritik:'Kritiker bemängeln, dass sein hedonistisches Kalkül in der Praxis zu vage bleibt, um konkrete Handlungsentscheidungen wirklich anzuleiten – zudem war „Der Garten" trotz seines egalitären Rufs eine recht kleine, elitäre Gemeinschaft.'},{id:'seneca',biografie:'Römischer Senator, immens wohlhabend, wurde Erzieher und später Berater des jungen Kaisers Nero. 65 n. Chr. von Nero, seinem einstigen Zögling, zum Suizid gezwungen, nachdem er einer Verschwörung verdächtigt wurde.',theorie:'Vertrat eine praxisnahe Stoa: Nur das eigene Urteil steht in unserer Macht, nicht äußere Umstände. Zeit sei der wertvollste, aber meistverschwendete Besitz des Menschen.',funfact:'Trotz seiner philosophischen Lehren zur Genügsamkeit gehörte Seneca zu den reichsten Männern Roms – ein Widerspruch, den schon seine Zeitgenossen offen kritisierten.',kritik:'Der eklatante Gegensatz zwischen gepredigter Bescheidenheit und tatsächlichem Reichtum sowie seiner Nähe zur Macht eines Tyrannen wird bis heute als Beispiel für die Kluft zwischen stoischer Theorie und gelebter Praxis angeführt.'},{id:'marcaurel',biografie:'Römischer Kaiser von 161 bis 180 n. Chr., einer der „Fünf guten Kaiser". Verbrachte einen Großteil seiner Herrschaft an den Grenzen des Reiches im Kampf gegen germanische Stämme und während einer verheerenden Pestepidemie.',theorie:'Praktizierte Stoizismus als gelebte Herrschaftsethik: Pflichterfüllung, Gleichmut gegenüber Schicksalsschlägen, ständige Erinnerung an die eigene Vergänglichkeit.',funfact:'Seine „Selbstbetrachtungen" waren ursprünglich ein rein privates Tagebuch, nie zur Veröffentlichung gedacht – vermutlich nachts in Feldlagern während seiner Feldzüge verfasst.',kritik:'Trotz seiner philosophischen Ideale von Milde und Selbstbeherrschung setzte er die Christenverfolgung fort und führte fortwährend Kriege – ein Spannungsfeld zwischen stoischem Ideal und politischer Realität.'},{id:'augustinus',biografie:'Verbrachte seine Jugend in Nordafrika mit, wie er selbst in den „Confessiones" beschreibt, ausschweifendem Lebensstil, bevor er sich Jahre später zum Christentum bekehrte. Wurde später Bischof von Hippo und einer der einflussreichsten Kirchenväter überhaupt.',theorie:'Verband platonisches Denken mit christlicher Theologie; untersuchte Zeit, Erinnerung und die Rolle der Gnade im menschlichen Willen. Prägte die westliche Vorstellung von Erbsünde entscheidend mit.',funfact:'Berühmt ist sein Gebet aus seiner Jugendzeit: „Gib mir Keuschheit und Enthaltsamkeit – aber nicht jetzt gleich."',kritik:'Seine Lehre von Erbsünde und Prädestination wird bis heute kritisiert, weil sie in der christlichen Tradition oft zu tief verwurzelten Schuldgefühlen beigetragen habe; auch sein Frauenbild spiegelt deutlich die patriarchalen Normen seiner Zeit.'},{id:'aquin',biografie:'Stammte aus italienischem Adel, trat gegen den Willen seiner Familie in den Dominikanerorden ein. Wegen seiner Schweigsamkeit und Körperfülle von Mitschülern spöttisch „der stumme Ochse" genannt – sein Lehrer Albertus Magnus soll darauf prophezeit haben, dieser „Ochse" werde eines Tages die ganze Welt mit seinem Gebrüll erfüllen.',theorie:'Verband aristotelische Logik systematisch mit christlicher Theologie; entwickelte die „Fünf Wege", rationale Argumente für die Existenz Gottes.',funfact:'Der Überlieferung nach war Aquin so beleibt, dass eigens ein halbmondförmiges Stück aus seinem Schreibtisch ausgeschnitten wurde, damit er bequem daran sitzen konnte.',kritik:'Kritiker bemängeln, dass seine Synthese die Philosophie letztlich der Theologie unterordnet – freies philosophisches Fragen bleibt stets an vorgegebene Glaubenswahrheiten gebunden.'},{id:'descartes',biografie:'Diente zeitweise als Söldner in verschiedenen europäischen Armeen, bevor er sich ganz der Philosophie und Mathematik widmete. Starb 1650 in Stockholm an einer Lungenentzündung, vermutlich weil Königin Christina von Schweden auf frühmorgendlichen Philosophieunterricht in eisiger Kälte bestand.',theorie:'Entwickelte durch methodischen Zweifel das „Cogito ergo sum" als unerschütterliches Wissensfundament; begründete den neuzeitlichen Dualismus von Geist und Körper.',funfact:'Descartes soll seine bahnbrechenden philosophischen Einsichten teilweise aus einer Serie lebhafter Träume gewonnen haben, die er in einer einzigen Nacht im Jahr 1619 hatte.',kritik:'Sein Leib-Seele-Dualismus steht bis heute vor dem ungelösten „Interaktionsproblem": Wie genau soll ein nicht-physischer Geist einen physischen Körper kausal beeinflussen können?'},{id:'spinoza',biografie:'Wuchs in einer jüdisch-portugiesischen Exilantenfamilie in Amsterdam auf, wurde mit 23 Jahren wegen „abscheulicher Ketzereien" aus der jüdischen Gemeinde exkommuniziert. Verdiente seinen Lebensunterhalt fortan als Linsenschleifer und lehnte einen angebotenen Lehrstuhl ab, um seine Unabhängigkeit zu bewahren.',theorie:'Vertrat radikalen Pantheismus: Gott und Natur seien identisch (Deus sive Natura); alles folge mit geometrischer Notwendigkeit aus der einen unendlichen Substanz.',funfact:'Starb vermutlich an einer Lungenkrankheit, die durch das jahrelange Einatmen von Glasstaub beim Linsenschleifen verursacht wurde – seine philosophische Unabhängigkeit hatte ihn wortwörtlich etwas gekostet.',kritik:'Sein strikter Determinismus lässt kaum Raum für echte menschliche Willensfreiheit oder moralische Verantwortung im herkömmlichen Sinn – ein Spannungspunkt, den Kritiker bis heute diskutieren.'},{id:'locke',biografie:'Arbeitete zeitweise als Arzt und war persönlicher Berater des Grafen von Shaftesbury. War zudem an der Ausarbeitung einer Verfassung für die englische Kolonie Carolina beteiligt und hielt selbst Anteile an Sklavenhandelsunternehmen.',theorie:'Der Geist sei bei Geburt eine „tabula rasa" – alles Wissen entstehe aus Erfahrung. Legte mit Naturrechten (Leben, Freiheit, Eigentum) die Grundlage liberaler Staatstheorie.',funfact:'Locke verfasste seine einflussreichen politischen Schriften teils im Untergrund und anonym, während er wegen seiner regierungskritischen Verbindungen zeitweise ins niederländische Exil fliehen musste.',kritik:'Seine praktische Verstrickung in koloniale und sklavenhalterische Strukturen steht in scharfem Kontrast zu seiner Theorie universeller Freiheitsrechte – ein oft diskutierter blinder Fleck seines liberalen Denkens.'},{id:'hume',biografie:'Wurde wegen seines offenen religiösen Skeptizismus als „der große Ungläubige" bekannt und deshalb zweimal eine Universitätsprofessur verweigert. Blieb dennoch zeitlebens gesellig und beliebt, seine Freunde nannten ihn liebevoll „le bon David".',theorie:'Radikaler Empirismus: Kausalität sei keine logische Notwendigkeit, sondern bloße Gewohnheit aus wiederholter Beobachtung – auch Induktion selbst lasse sich rational nicht letztgültig rechtfertigen.',funfact:'Hume blieb auf seinem Sterbebett bemerkenswert gelassen und humorvoll und scherzte gegenüber Besuchern über mögliche Ausreden, die er einem zornigen Gott im Jenseits präsentieren könnte, falls es ihn doch gäbe.',kritik:'Sein Skeptizismus gegenüber der Induktion untergräbt letztlich die rationale Rechtfertigung der Naturwissenschaft selbst – ein bis heute ungelöstes philosophisches Rätsel, das als „Humes Problem" bekannt ist.'},{id:'rousseau',biografie:'Wuchs in Genf auf, führte ein unstetes Wanderleben quer durch Europa. Gab entgegen seinen einflussreichen pädagogischen Schriften alle fünf eigenen Kinder in ein Findelhaus, wo die meisten früh starben.',theorie:'Der Mensch sei von Natur aus gut, werde aber durch die Gesellschaft korrumpiert. Legitime politische Ordnung müsse dem „Gemeinwillen" der Bürgerschaft folgen.',funfact:'Trotz seines Rufs als Naturphilosoph liebte Rousseau exzentrische Kleidung und trug zeitweise armenische Tracht, weil er sie für besonders bequem hielt.',kritik:'Der eklatante Widerspruch zwischen seinen einflussreichen Erziehungsideen in „Émile" und dem Verlassen der eigenen Kinder gilt vielen als eine der größten Ironien der Philosophiegeschichte.'},{id:'kant',biografie:'Verließ seine Heimatstadt Königsberg zeitlebens nie um mehr als etwa 16 Kilometer. Sein Tagesablauf war legendär präzise – Nachbarn sollen ihre Uhren nach seinem täglichen Nachmittagsspaziergang gestellt haben. Blieb zeitlebens unverheiratet.',theorie:'Entwickelte den Kategorischen Imperativ als oberstes Moralprinzip; unterschied zwischen der Welt, wie sie an sich ist, und der Welt, wie sie uns durch unsere Verstandeskategorien erscheint.',funfact:'Der Legende nach unterbrach Kant seinen täglichen Spaziergang genau ein einziges Mal in seinem Leben – aus Begeisterung über die Nachricht von der Französischen Revolution.',kritik:'Kritiker bemängeln die Starrheit des Kategorischen Imperativs: Er scheint keine Ausnahmen zuzulassen, selbst in Extremfällen wie einer Lüge, um einen unschuldigen Menschen vor einem Mörder zu schützen.'},{id:'hegel',biografie:'Zunächst wenig erfolgreich, wurde erst spät in seiner Karriere zum gefeierten Star der deutschen Philosophie und erhielt einen prestigeträchtigen Lehrstuhl in Berlin. Starb 1831 während einer Choleraepidemie.',theorie:'Entwickelte die Dialektik (These–Antithese–Synthese) als Motor der Geschichte, in der sich der „Weltgeist" fortschreitend seiner selbst bewusst wird.',funfact:'Auf seinem Sterbebett soll Hegel bemerkt haben, nur ein einziger Schüler habe ihn je wirklich verstanden – um dann hinzuzufügen, dass selbst dieser ihn eigentlich missverstanden habe.',kritik:'Seine notorisch dichte, oft dunkle Sprache macht sein System schwer überprüfbar – Kritiker wie Popper warfen ihm vor, eine im Grunde unfalsifizierbare Geschichtsmetaphysik zu betreiben.'},{id:'marx',biografie:'Verbrachte den Großteil seines Erwachsenenlebens im Londoner Exil in relativer Armut, finanziell unterstützt von seinem Freund Friedrich Engels. Mehrere seiner Kinder starben früh, teils an den Folgen der Armut der Familie.',theorie:'Historischer Materialismus: Ökonomische Verhältnisse bestimmten Gesellschaft und Bewusstsein; Klassenkampf sei der zentrale Motor geschichtlicher Entwicklung.',funfact:'Marx verbrachte Jahre damit, täglich im Lesesaal des Britischen Museums zu recherchieren – sein Stammplatz dort ist bis heute eine Art Pilgerstätte für Marx-Interessierte.',kritik:'Die von ihm vorhergesagten proletarischen Revolutionen in hochindustrialisierten Ländern blieben aus; zudem führten die im 20. Jahrhundert unter Berufung auf ihn errichteten Regime zu enormem menschlichem Leid.'},{id:'nietzsche',biografie:'Litt zeitlebens unter schweren Migräneanfällen und gesundheitlichen Problemen. Brach 1889 in Turin öffentlich zusammen, nachdem er angeblich ein misshandeltes Pferd umarmt hatte, und verbrachte sein letztes Lebensjahrzehnt geistig umnachtet in der Obhut seiner Familie.',theorie:'Verkündete den „Tod Gottes" und radikale Kritik an traditioneller Moral; Wille zur Macht als treibende Kraft allen Lebens; der Übermensch als Selbstüberwindung des bisherigen Menschen.',funfact:'Nietzsches Schwester Elisabeth bearbeitete nach seinem geistigen Zusammenbruch und Tod seine Schriften und -Nachlass, um sie später mit deutschnationalen und antisemitischen Ideen in Einklang zu bringen, die Nietzsche selbst zu Lebzeiten scharf ablehnte.',kritik:'Die spätere Vereinnahmung seiner Ideen durch den Nationalsozialismus – maßgeblich durch die Manipulationen seiner Schwester – steht in direktem Widerspruch zu Nietzsches eigener, wiederholt geäußerter Verachtung für Antisemitismus und deutschen Nationalismus.'},{id:'kierkegaard',biografie:'Löste kurz vor der Hochzeit überraschend seine Verlobung mit Regine Olsen – ein Ereignis, das sein gesamtes weiteres Werk emotional durchzieht. Wurde von einem dänischen Satiremagazin jahrelang gnadenlos wegen seines Aussehens und Auftretens verspottet.',theorie:'Vorläufer des Existentialismus: Angst als Grundstimmung menschlicher Freiheit; Glaube als „Sprung" jenseits ethischer Vernunftlogik.',funfact:'Kierkegaard veröffentlichte viele seiner Werke unter kunstvoll erfundenen Pseudonymen, die jeweils eigene, teils widersprüchliche philosophische Perspektiven vertraten.',kritik:'Sein Konzept des „Sprungs des Glaubens" wird als grundsätzlich irrational kritisiert – es liefert kein Kriterium, um echten Glauben von bloßer Selbsttäuschung zu unterscheiden.'},{id:'schopenhauer',biografie:'Notorisch menschenscheu und misanthropisch, hielt sich einen Pudel, den er liebevoll „Atman" nannte. Warf einst eine Nachbarin, die ihn gestört hatte, die Treppe hinunter und musste ihr daraufhin gerichtlich eine lebenslange Rente zahlen.',theorie:'Ein blinder, zielloser „Wille" liege allem zugrunde und erzeuge endloses Leiden; Erlösung sei nur durch ästhetische Kontemplation oder Verneinung des Willens möglich.',funfact:'Schopenhauer speiste jeden Tag pünktlich um vier Uhr im selben Gasthaus und legte vor jeder Mahlzeit demonstrativ eine Goldmünze auf den Tisch, die er nur dann für die Armen spendete, wenn niemand am Nachbartisch über etwas anderes als Philosophie sprach.',kritik:'Sein durchgängiger Pessimismus wird als zu totalisierend kritisiert; zudem gelten seine offen frauenfeindlichen Schriften als ernsthafter Schandfleck seines sonst einflussreichen Werks.'},{id:'sartre',biografie:'Lehnte 1964 demonstrativ den Nobelpreis für Literatur ab, mit der Begründung, ein Schriftsteller solle sich nicht in eine Institution verwandeln lassen. Führte eine lebenslange, offene Beziehung mit Simone de Beauvoir, ohne je zu heiraten.',theorie:'„Existenz geht der Essenz voraus" – der Mensch entwirft sich durch seine Entscheidungen selbst und ist „zur Freiheit verurteilt", mit voller Verantwortung für sein Handeln.',funfact:'Sartre war körperlich sehr klein und auf einem Auge fast blind, dennoch beschrieb er sich selbst humorvoll als überzeugt, unwiderstehlich attraktiv zu wirken – kraft reiner Rhetorik.',kritik:'Seine Vorstellung radikaler, fast unbegrenzter Freiheit wird kritisiert, weil sie reale soziale, ökonomische und biologische Zwänge unterschätzt, denen Menschen tatsächlich unterliegen.'},{id:'beauvoir',biografie:'Eine der ersten Frauen, die an der renommierten École Normale Supérieure in Paris zugelassen wurden. Führte zeitlebens eine offene Partnerschaft mit Jean-Paul Sartre und hatte daneben weitere bedeutende Beziehungen zu Männern und Frauen.',theorie:'Untersuchte die gesellschaftliche Konstruktion von Weiblichkeit; „Man kommt nicht als Frau zur Welt, man wird es" – Geschlecht als von Gesellschaft geformte Rolle, nicht bloße Biologie.',funfact:'Beauvoir bestand die schwierige „Agrégation"-Prüfung in Philosophie als jüngste Kandidatin ihres Jahrgangs und landete denkbar knapp hinter Sartre auf dem zweiten Platz.',kritik:'Spätere Feministinnen kritisierten, dass ihr Ansatz stark aus der Perspektive einer weißen, gebildeten, westlichen Frau geschrieben sei und andere Erfahrungen von Weiblichkeit zu wenig berücksichtige.'},{id:'camus',biografie:'Wuchs in bitterer Armut in Algerien auf, sein Vater fiel im Ersten Weltkrieg, als Camus noch ein Kleinkind war. Starb 1960 im Alter von nur 46 Jahren bei einem Autounfall – in seiner Jackentasche fand man ein ungenutztes Zugticket, da er ursprünglich mit dem Zug hatte reisen wollen.',theorie:'Absurdismus: Der menschliche Sinnwunsch trifft auf ein sinnfreies Universum – trotziges, bewusstes Weiterleben statt Verzweiflung oder Flucht sei die angemessene Antwort.',funfact:'Bevor er Schriftsteller wurde, war Camus leidenschaftlicher Amateur-Torwart und sagte später scherzhaft, er habe alles, was er über Moral wisse, dem Fußball zu verdanken.',kritik:'Sein zurückhaltender, differenzierter Standpunkt zum Algerienkrieg enttäuschte viele seiner Zeitgenossen – u.a. Sartre – zutiefst und führte zum öffentlichen Bruch der beiden einst befreundeten Denker.'},{id:'arendt',biografie:'Hatte als junge Studentin eine intensive, später kontrovers diskutierte Liebesbeziehung zu ihrem Lehrer Martin Heidegger. Musste als Jüdin vor den Nationalsozialisten aus Deutschland fliehen und emigrierte über Frankreich in die USA.',theorie:'Analysierte totalitäre Herrschaft und prägte den Begriff der „Banalität des Bösen" – erschreckend gewöhnliche, gedankenlose Bürokraten statt dämonischer Täter.',funfact:'Trotz Heideggers späterer NSDAP-Mitgliedschaft erneuerte Arendt nach dem Krieg den Kontakt zu ihm und setzte sich sogar für die Veröffentlichung seiner Werke ein – ein bis heute kontrovers diskutiertes Kapitel ihrer Biografie.',kritik:'Ihre These der „Banalität des Bösen" wurde kritisiert, weil neuere historische Forschung nahelegt, dass Eichmann ideologisch überzeugter und weniger „gedankenlos" gehandelt haben könnte, als Arendt in ihrem Bericht darstellte.'},{id:'foucault',biografie:'Arbeitete zeitweise in Tunesien und Polen, engagierte sich später aktiv in der Bewegung für Gefangenenrechte und in der frühen LGBT-Bewegung Frankreichs. Starb 1984 an einer AIDS-bedingten Krankheit, was zu seiner Zeit noch tabuisiert war.',theorie:'Macht und Wissen seien untrennbar verwoben; Institutionen formten Subjekte über Disziplin und Diskurse, subtiler als durch offene Zwangsmittel.',funfact:'Foucault war begeisterter Bergsteiger und Höhlenforscher und nutzte laut eigenen Aussagen halluzinogene Drogen, um neue Denkperspektiven für seine Philosophie zu gewinnen.',kritik:'Kritiker bemängeln, dass sein durchgängiger Fokus auf Macht kaum eine Grundlage für echte Emanzipation oder normative Kritik bietet: Wenn wirklich alles Macht ist, worauf genau könnte Widerstand dann überhaupt beruhen?'},{id:'wittgenstein',biografie:'Entstammte einer der reichsten Familien Österreichs, verschenkte jedoch sein gesamtes ererbtes Vermögen und arbeitete zeitweise als Volksschullehrer und Klostergärtner, bevor er nach Cambridge zurückkehrte.',theorie:'Frühwerk: Die Grenzen der Sprache seien die Grenzen der Welt. Spätwerk: Bedeutung entstehe erst durch den konkreten Gebrauch in „Sprachspielen", nicht durch feste Definitionen.',funfact:'Wittgenstein war leidenschaftlicher Konstrukteur und entwarf zeitweise Flugzeugpropeller sowie ein komplett von ihm selbst geplantes und gebautes minimalistisches Haus für seine Schwester in Wien.',kritik:'Seine Wende zum Spätwerk lässt viele grundsätzliche Fragen offen: Es bleibt unklar, wie genau Bedeutung innerhalb eines „Sprachspiels" letztlich verbindlich fixiert wird.'},{id:'konfuzius',biografie:'Verbrachte einen Großteil seines Lebens wandernd durch mehrere chinesische Fürstentümer, auf der Suche nach einem Herrscher, der bereit war, seine Lehren umzusetzen – zu Lebzeiten weitgehend erfolglos. Seine Ideen wurden erst Jahrhunderte nach seinem Tod zur offiziellen Staatsdoktrin.',theorie:'Ren (Menschlichkeit) und Li (angemessene Riten) als zentrale Tugenden; gute Herrschaft beruhe auf moralischem Vorbild statt auf Zwang.',funfact:'Der Legende nach war Konfuzius außergewöhnlich groß gewachsen – Überlieferungen sprechen von fast zwei Metern Körpergröße, was ihn unter seinen Zeitgenossen optisch stark auffallen ließ.',kritik:'Kritiker sehen in seiner starken Betonung von Hierarchie und kindlicher Pietät eine Grundlage, die starre, patriarchale Sozialstrukturen über Jahrhunderte zementiert und legitimiert hat.'},{id:'buddha',biografie:'Der Überlieferung zufolge ein Prinz (Siddhartha Gautama), der behütet in einem Palast aufwuchs, bis er bei Ausflügen erstmals Alter, Krankheit und Tod erblickte („Vier Ausfahrten") und daraufhin sein Leben komplett änderte.',theorie:'Die Vier Edlen Wahrheiten über Leiden und seine Überwindung; Anatta – die Lehre, dass es kein dauerhaftes, unveränderliches Selbst gibt.',funfact:'Vor seiner Erleuchtung praktizierte er Jahre extremer Askese, angeblich bis er so ausgemergelt war, dass er seine Wirbelsäule durch die Bauchdecke ertasten konnte – erst danach fand er den „Mittleren Weg".',kritik:'Historiker weisen darauf hin, dass die traditionelle Biografie erst Jahrhunderte nach seinem Tod schriftlich fixiert wurde, was ihre historische Zuverlässigkeit im Detail erschwert.'},{id:'laozi',biografie:'Eine teils legendäre Gestalt – manche Historiker bezweifeln, dass er als einzelne historische Person existierte, oder vermuten, dass mehrere Autoren hinter dem zugeschriebenen Namen stehen. Der Überlieferung nach ritt er am Ende seines Lebens auf einem Wasserbüffel gen Westen davon und wurde nie wieder gesehen.',theorie:'Das Dao als unbenennbares Urprinzip aller Dinge; Wu Wei – müheloses Handeln im Einklang mit dem natürlichen Lauf der Dinge statt aktivem Eingreifen.',funfact:'Der Legende nach soll er erst geschrieben haben, nachdem ein Grenzwächter ihn bat, seine Weisheit niederzulegen, bevor er die Zivilisation für immer verließ – daraus entstand angeblich das gesamte Dao De Jing.',kritik:'Die ungeklärte historische Existenz der Figur selbst erschwert jede gesicherte biografische oder werkgeschichtliche Aussage über „Laozi" erheblich.'},{id:'byungchulhan',biografie:'Studierte ursprünglich Metallurgie in Südkorea, bevor er nach Deutschland zog, um Philosophie, deutsche Literatur und katholische Theologie zu studieren. Lehrt heute an der Universität der Künste Berlin und gibt bewusst nur sehr selten Interviews oder öffentliche Auftritte.',theorie:'Diagnostiziert die heutige „Leistungsgesellschaft": Erschöpfung entstehe nicht mehr durch äußeren Zwang, sondern durch selbst auferlegten Optimierungsdruck; kritisiert zudem die „Transparenzgesellschaft" permanenter Selbstoffenlegung.',funfact:'Han vermeidet konsequent Fotos und öffentliche Auftritte, gibt kaum Interviews und ist damit einer der medienscheusten bekannten zeitgenössischen Philosophen überhaupt.',kritik:'Kritiker werfen ihm vor, seine kulturdiagnostischen Thesen seien oft breite, pointierte Verallgemeinerungen mit wenig empirisch-soziologischer Absicherung – eindrucksvoll formuliert, aber schwer überprüfbar.'},{id:'montaigne',biografie:'Sohn eines wohlhabenden Kaufmanns und Bürgermeisters von Bordeaux, wuchs eigenwillig zweisprachig auf – sein Vater ließ ihn zunächst ausschließlich Latein sprechen, bevor er Französisch lernte. Zog sich mit 38 Jahren weitgehend aus dem öffentlichen Leben in den Turm seines Schlosses zurück, um sich ganz dem Lesen und Schreiben zu widmen, wurde später aber dennoch zweimal Bürgermeister von Bordeaux. Litt zeitlebens an schmerzhaften Nierensteinen.',theorie:'Begründete den Essay als literarische Form offenen, tastenden Selbstnachdenkens; vertrat einen milden Skeptizismus („Que sais-je?") und einen frühen kulturellen Relativismus gegenüber fremden Lebensweisen.',funfact:'Ließ sich Sinnsprüche und Zitate lateinischer und griechischer Autoren direkt in die Deckenbalken seiner Turmbibliothek schnitzen, sodass er beim Nachdenken buchstäblich von ihnen umgeben war – rund 54 dieser Inschriften sind bis heute erhalten.',kritik:'Kritiker bemängeln, dass sein bewusst unsystematischer, „schweifender" Essaystil es schwer macht, eine kohärente eigene Lehre aus seinem Werk herauszudestillieren – Bewunderer sehen darin allerdings gerade die Stärke seines undogmatischen, ehrlichen Denkens.'},{id:'machiavelli',biografie:'Diente als Diplomat und Kanzleisekretär der Republik Florenz, bevor die Rückkehr der Medici ihn 1512 ins politische Aus und kurzzeitig sogar ins Gefängnis brachte, wo er gefoltert wurde. Schrieb „Der Fürst" in der erzwungenen Muße seines Landexils, in der Hoffnung, sich bei den Medici wieder Gehör zu verschaffen.',theorie:'Trennte Politik konsequent von traditioneller Morallehre; ein Herrscher müsse pragmatisch handeln, notfalls hart oder täuschend, um Macht und Ordnung zu sichern.',funfact:'Der Legende nach zog sich Machiavelli beim abendlichen Schreiben festliche Gewänder an, um sich – wie er selbst schrieb – „würdig" den imaginären Gesprächen mit den großen Denkern der Antike in seiner Bibliothek zu nähern.',kritik:'Sein Name wurde zum Synonym für skrupellose Machtpolitik („machiavellistisch"), obwohl Historiker bis heute streiten, ob „Der Fürst" zynischer Ratgeber oder versteckte Kritik an genau dieser Machtpolitik war.'},{id:'hobbes',biografie:'Wurde der Überlieferung nach vorzeitig geboren, als seine Mutter von der Nachricht der heranrückenden spanischen Armada erschreckt wurde – er scherzte später, Furcht und er seien „Zwillinge". Diente als Tutor mehrerer englischer Adelsfamilien und floh während des englischen Bürgerkriegs ins französische Exil.',theorie:'Entwarf im „Leviathan" eine Staatstheorie, nach der nur ein starker Souverän Menschen vor dem Naturzustand des „Krieges aller gegen alle" bewahren kann.',funfact:'Hobbes war ein begeisterter Tennisspieler und soll noch mit über 70 Jahren regelmäßig gespielt haben, weil er körperliche Bewegung für geistige Klarheit für unerlässlich hielt.',kritik:'Sein pessimistisches Menschenbild und die Rechtfertigung nahezu unbegrenzter Souveränsmacht wird bis heute kritisiert, da er kaum Mechanismen gegen Machtmissbrauch des Souveräns selbst vorsieht.'},{id:'voltaire',biografie:'Eigentlich François-Marie Arouet, nahm das Pseudonym „Voltaire" nach einer Haftstrafe in der Bastille an, in die ihn eine satirische Beleidigung gegen den französischen Adel gebracht hatte. Musste mehrfach ins Exil, unter anderem nach England, was seinen Blick für vergleichende Gesellschaftskritik schärfte.',theorie:'Vertrat scharfe Kritik an religiösem Dogmatismus und Intoleranz; Vernunft und Toleranz als Grundpfeiler der Aufklärung.',funfact:'Voltaire war zeitlebens ein cleverer Geschäftsmann und wurde durch geschickte Lotterie- und Finanzspekulationen einer der reichsten Schriftsteller seiner Zeit.',kritik:'Trotz seines Eintretens für Toleranz enthalten einige seiner Schriften antisemitische Passagen, die heutige Historiker als ernsthaften Widerspruch zu seinem aufklärerischen Anspruch werten.'},{id:'mill',biografie:'Wurde von seinem Vater James Mill einem intensiven Bildungsexperiment unterzogen – lernte bereits als Kind Griechisch, erlitt mit 20 Jahren eine schwere Nervenkrise, die er selbst auf diese überfrachtete Erziehung zurückführte. Arbeitete Jahrzehnte für die British East India Company.',theorie:'Utilitarismus: Handlungen sind gut, wenn sie das größte Glück der größten Zahl fördern; starkes Plädoyer für individuelle Freiheit.',funfact:'Mill führte eine jahrzehntelange, tief intellektuelle Partnerschaft mit Harriet Taylor, die er selbst als maßgeblichen Mitverfasser vieler seiner Ideen bezeichnete – sie durften aufgrund gesellschaftlicher Konventionen erst nach dem Tod ihres ersten Mannes heiraten.',kritik:'Kritiker bemängeln, dass sein Utilitarismus in Grenzfällen individuelle Rechte zugunsten des Gesamtnutzens preisgeben könnte – ein bis heute zentraler Einwand gegen rein konsequentialistische Ethik.'},{id:'popper',biografie:'Wuchs in Wien in einer assimilierten jüdischen Familie auf, floh 1937 vor dem Nationalsozialismus nach Neuseeland und emigrierte später nach England. Arbeitete zeitweise als Möbeltischler, bevor er sich vollständig der Philosophie widmete.',theorie:'Falsifikationismus: Wissenschaftliche Theorien lassen sich nie endgültig beweisen, nur widerlegen; verteidigte die „offene Gesellschaft" gegen totalitäre Geschichtsphilosophien.',funfact:'Bei einem berühmten Treffen mit Wittgenstein 1946 in Cambridge kam es zu einem hitzigen Streit, bei dem Wittgenstein angeblich mit einem Schürhaken gestikulierte, bevor er den Raum verließ.',kritik:'Kritiker werfen ein, dass reine Falsifizierbarkeit als Kriterium zu streng sei – viele anerkannte wissenschaftliche Theorien lassen sich in der Praxis nicht so einfach eindeutig falsifizieren, wie Poppers Modell nahelegt.'},{id:'rawls',biografie:'Diente im Zweiten Weltkrieg im Pazifik und war kurz nach dem Atombombenabwurf Zeuge der Zerstörung Hiroshimas, was ihn zutiefst prägte. Lehrte jahrzehntelang zurückgezogen in Harvard und galt als bemerkenswert bescheiden trotz seines enormen Einflusses.',theorie:'Entwickelte den „Schleier des Nichtwissens" als Gedankenexperiment, um gerechte Gesellschaftsprinzipien unabhängig von Eigeninteresse zu bestimmen.',funfact:'Rawls arbeitete über zwei Jahrzehnte an seiner „Theorie der Gerechtigkeit", bevor er sie 1971 veröffentlichte – und überarbeitete sie danach noch mehrfach als Reaktion auf Kritik.',kritik:'Kritiker wie Nozick warfen ein, dass Rawls\' Umverteilungsgerechtigkeit individuelle Eigentumsrechte zu wenig respektiere; kommunitaristische Kritiker wie Sandel bemängelten sein Bild eines von Gemeinschaft „unbelasteten" Individuums.'},{id:'zhuangzi',biografie:'Der Überlieferung nach lebte er in bescheidenen Verhältnissen und lehnte ein angebotenes Ministeramt mit dem Gleichnis ab, er wolle lieber wie eine Schildkröte frei im Schlamm kriechen als tot und verehrt in einem Palast liegen.',theorie:'Relativierte menschliche Urteile radikal durch Gleichnisse wie den Schmetterlingstraum; Freiheit entsteht durch Loslassen starrer Kategorien.',funfact:'Der Legende nach soll er beim Tod seiner Frau zunächst getrauert, dann aber fröhlich Trommel gespielt haben – mit der Begründung, ihr Tod sei nur eine natürliche Rückkehr zum kosmischen Kreislauf.',kritik:'Kritiker bemängeln, dass sein radikaler Relativismus letztlich jede feste ethische oder politische Position unterminiert – wenn alle Perspektiven gleich gültig sind, wie lässt sich dann noch begründet für irgendetwas eintreten?'},{id:'epiktet',biografie:'Wurde als Sklave geboren und diente in Rom, wo sein Herr ihm der Überlieferung nach das Bein brach – Epiktet soll dies mit stoischer Gelassenheit ertragen haben. Nach seiner Freilassung gründete er eine eigene Philosophenschule in Griechenland.',theorie:'Dichotomie der Kontrolle: Unterscheide zwischen dem, was in deiner Macht steht (Urteile, Wille), und dem, was es nicht tut.',funfact:'Epiktet besaß der Überlieferung nach kaum persönlichen Besitz – lediglich eine Strohmatte, eine Lampe und einen einfachen Becher, ganz im Einklang mit seiner eigenen Lehre der Genügsamkeit.',kritik:'Kritiker bemängeln, dass die stoische Betonung innerer Gelassenheit angesichts äußerer Umstände in der Praxis dazu missbraucht werden kann, echtes gesellschaftliches Unrecht zu relativieren, statt es zu bekämpfen.'},{id:'heidegger',biografie:'Wurde 1933 Rektor der Universität Freiburg und trat noch im selben Jahr der NSDAP bei, ein Schritt, den er nach dem Krieg nie wirklich öffentlich aufgearbeitet hat. Zog sich später in seine Hütte im Schwarzwald zurück, wo ein Großteil seines späteren Denkens entstand.',theorie:'Untersuchung des „Daseins" und seiner Geworfenheit in die Welt; Sein-zum-Tode als Grundbedingung authentischer Existenz.',funfact:'Heideggers Hütte in Todtnauberg hatte weder elektrischen Strom noch fließendes Wasser – er bestand darauf, dass echtes Denken nur im einfachen, bodenständigen Landleben möglich sei.',kritik:'Seine NSDAP-Mitgliedschaft und das Fehlen einer öffentlichen, unmissverständlichen Distanzierung nach 1945 werfen bis heute einen Schatten auf sein Werk und die Frage, wie stark seine Philosophie selbst mit dieser Politik verwoben war.'},{id:'husserl',biografie:'Studierte ursprünglich Mathematik, bevor er sich der Philosophie zuwandte. Wurde 1933 als „nicht-arisch" von den Nationalsozialisten von der Lehre ausgeschlossen; sein einstiger Schüler Heidegger widmete ihm später nicht einmal mehr die zuvor zugeeignete Fassung von „Sein und Zeit".',theorie:'Begründete die Phänomenologie: „Zu den Sachen selbst" – Bewusstseinsphänomene unvoreingenommen beschreiben.',funfact:'Husserl hinterließ bei seinem Tod über 40.000 Seiten unveröffentlichter stenografischer Manuskripte, die nur durch eine dramatische Rettungsaktion eines belgischen Franziskanerpaters vor der Vernichtung durch die Nationalsozialisten bewahrt wurden.',kritik:'Kritiker bemängeln, dass seine phänomenologische Methode letztlich nie zu einer wirklich stabilen, allgemein anerkannten „strengen Wissenschaft" wurde, wie er selbst gehofft hatte.'},{id:'russell',biografie:'Wuchs als Waise bei seinen strengen Großeltern auf, saß im Ersten Weltkrieg wegen pazifistischer Aktivität im Gefängnis, wo er sein Werk „Einführung in die mathematische Philosophie" verfasste. Erhielt 1950 den Nobelpreis für Literatur.',theorie:'Mitbegründer der analytischen Philosophie; versuchte, Mathematik vollständig auf Logik zurückzuführen.',funfact:'Russell war viermal verheiratet und blieb bis ins hohe Alter politisch aktiv – noch mit über 90 Jahren wurde er wegen Protesten gegen atomare Aufrüstung kurzzeitig inhaftiert.',kritik:'Sein eigenes Grundlagenprojekt der Mathematik (Principia Mathematica) wurde durch Gödels Unvollständigkeitssätze in seinen ursprünglichen Ambitionen erschüttert – ein Rückschlag, den Russell selbst offen anerkannte.'},{id:'leibniz',biografie:'Ein echter Universalgelehrter – arbeitete gleichzeitig als Diplomat, Bibliothekar, Historiker und Mathematiker am Hof von Hannover. Entwickelte unabhängig von Newton die Infinitesimalrechnung, was zu einem erbitterten, jahrzehntelangen Prioritätsstreit zwischen beiden führte.',theorie:'Die Welt bestehe aus unteilbaren „Monaden"; unsere Welt sei die „beste aller möglichen Welten".',funfact:'Leibniz entwarf früh mechanische Rechenmaschinen, die neben Addition auch Multiplikation und Division ausführen konnten – weit seiner Zeit voraus.',kritik:'Sein optimistischer Grundsatz von der „besten aller möglichen Welten" wurde von Voltaire in „Candide" beißend satirisch verspottet, gerade angesichts realer Katastrophen wie des Erdbebens von Lissabon 1755.'},{id:'bacon',biografie:'War nicht nur Philosoph, sondern auch hochrangiger englischer Staatsbeamter und zeitweise Lordkanzler, bevor ihn ein Korruptionsskandal 1621 zu Fall brachte. Starb der Überlieferung nach an einer Erkältung, die er sich zuzog, als er ein Experiment durchführte: Er stopfte ein Hühnchen mit Schnee, um zu testen, ob Kälte Fäulnis verzögert.',theorie:'Begründete die induktive, empirische Erkenntnismethode gegen scholastische Deduktion; „Wissen ist Macht".',funfact:'Manche Verschwörungstheoretiker behaupten bis heute, Bacon habe in Wahrheit Shakespeares Werke verfasst – eine These, die von der etablierten Forschung praktisch einhellig zurückgewiesen wird.',kritik:'Bacons eigene wissenschaftliche Methode blieb in der praktischen Anwendung eher grob und wurde später durch differenziertere Wissenschaftstheorien (u.a. Popper) deutlich verfeinert.'},{id:'pascal',biografie:'Ein mathematisches Wunderkind – entwickelte bereits als Teenager eigenständig Sätze der Geometrie und baute mit 19 Jahren eine der ersten mechanischen Rechenmaschinen, um seinem Vater bei Steuerberechnungen zu helfen. Erlebte 1654 ein tiefes religiöses Erweckungserlebnis, das sein späteres Denken prägte.',theorie:'„Das Herz hat seine Gründe, die die Vernunft nicht kennt"; die berühmte „Pascalsche Wette" zur Rationalität des Gottesglaubens.',funfact:'Pascal litt zeitlebens an schweren gesundheitlichen Problemen und schlief der Überlieferung nach oft nur wenige Stunden – viele seiner „Pensées" wurden auf einzelnen, ungeordneten Zetteln verfasst.',kritik:'Kritiker bemängeln, dass seine „Wette" ein rein pragmatisches Nützlichkeitsargument für den Glauben liefert, das nichts über die tatsächliche Wahrheit der Existenz Gottes aussagt.'},{id:'feuerbach',biografie:'Sohn eines bekannten Strafrechtlers, wandte sich zunächst der Theologie zu, bevor ihn Hegels Vorlesungen zur Philosophie brachten. Seine religionskritischen Schriften kosteten ihn seine akademische Karriere – er verbrachte den Großteil seines späteren Lebens zurückgezogen auf dem Land.',theorie:'Religion sei eine Projektion menschlicher Ideale nach außen; Theologie sei im Kern verkappte Anthropologie.',funfact:'Feuerbach lebte die letzten Jahrzehnte seines Lebens in relativer Armut auf einem bayerischen Landgut, nachdem eine Porzellanfabrik, an der seine Frau beteiligt war, bankrottging.',kritik:'Kritiker wie Marx würdigten Feuerbachs Religionskritik zwar an, warfen ihm aber vor, bei einer rein abstrakten „Anthropologie" stehenzubleiben, ohne die konkreten gesellschaftlich-ökonomischen Ursachen religiöser Entfremdung zu analysieren.'},{id:'weber',biografie:'Litt jahrelang unter schweren nervösen Zusammenbrüchen, die ihn zeitweise fast vollständig arbeitsunfähig machten. Reiste 1904 in die USA, wo die dortige protestantische Geschäftskultur direkten Einfluss auf sein berühmtestes Werk hatte.',theorie:'Untersuchte, wie protestantische Arbeitsethik zur Entstehung des modernen Kapitalismus beitrug; prägte den Begriff der „Entzauberung der Welt".',funfact:'Weber hielt seine berühmte Vorlesung „Wissenschaft als Beruf" erst kurz vor seinem Tod – sie gilt bis heute als einer der einflussreichsten Texte zur Rolle der Wissenschaft in der modernen Gesellschaft.',kritik:'Kritiker bemängeln, dass sein Kausalzusammenhang zwischen protestantischer Ethik und Kapitalismusentstehung historisch zu einseitig sei und andere ökonomische Faktoren unterschätze.'},{id:'hypatia',biografie:'Lehrte in Alexandria Mathematik und Philosophie und war eine der angesehensten Gelehrten des spätantiken Mittelmeerraums; Schüler kamen aus dem gesamten Reich zu ihr. Wurde 415 n. Chr. während wachsender religiös-politischer Spannungen von einem christlichen Mob brutal ermordet.',theorie:'Vertrat neuplatonisches Denken, verbunden mit fundierter Mathematik und Astronomie; keine eigenen Schriften sind erhalten.',funfact:'Sie soll oft in einfacher Gelehrtenkleidung durch Alexandria gegangen sein und öffentlich philosophische Vorträge gehalten haben – für eine Frau ihrer Zeit ein höchst ungewöhnliches öffentliches Auftreten.',kritik:'Da keine ihrer eigenen Schriften erhalten sind, beruht praktisch alles, was wir über ihr Denken wissen, auf Berichten Dritter – ihr genauer philosophischer Beitrag lässt sich historisch nur eingeschränkt rekonstruieren.'},{id:'sunzi',biografie:'Historische Details seines Lebens sind unsicher und teils legendär – der Überlieferung nach diente er als General im Staat Wu und bewies seine Disziplin-Lehren angeblich, indem er selbst die Konkubinen des Königs erfolgreich zu einer disziplinierten Truppe drillte.',theorie:'Verfasste das älteste und einflussreichste Werk der Militärstrategie; der größte Sieg sei der, den Feind ohne Kampf zu bezwingen.',funfact:'„Die Kunst des Krieges" wird bis heute nicht nur an Militärakademien, sondern auch in Wirtschaftsschulen und von Sportmannschaften als Strategie-Lehrbuch verwendet.',kritik:'Manche Historiker bezweifeln, ob Sunzi überhaupt als einzelne historische Person existierte, oder ob der Text über Generationen von mehreren Militärstrategen zusammengetragen wurde.'}];
